package main

const nativeWorkspacePilot = `(async()=>{if(!document.querySelector("#source"))return;window.confirm=()=>true;const $=s=>document.querySelector(s);const wait=async(fn,ms=360000)=>{const end=Date.now()+ms;while(Date.now()<end){if(fn())return;await new Promise(r=>setTimeout(r,200))}throw Error('Native window pilot timed out: '+$('#status').textContent)};const report=async(ok,message)=>fetch('/api/self-test',{method:'POST',headers:{'Content-Type':'application/json','X-PageSpindle-Key':PILOT_KEY},body:JSON.stringify({ok,message})});try{if($('#workspace').hidden||$('#confirm-review'))throw Error('Workbench or optional-review contract failed');$('#source').value='This is a direct PageSpindle audiobook without passage review.';$('#render').click();await wait(()=>!$('#operation').hidden);await wait(()=>$('#operation').hidden);if($('#status').classList.contains('error'))throw Error($('#status').textContent);$('#downloads button').click();await wait(()=>$('#status').textContent.startsWith('Saved '));$('#save-project').click();await wait(()=>$('#status').textContent==='Project backup saved.');$('#clear').click();await wait(()=>$('#source').value==='');const source='The fictional library opens at 9:00 and closes at 5:00. Keep the well-known path.';$('#source').value=source;$('#prepare-ai').click();await wait(()=>!$('#operation').hidden);await wait(()=>$('#operation').hidden);if($('#status').classList.contains('error')||$('#source').value!==source||$('#prepared').value.trim()!==source)throw Error('Actual native AI/source pilot failed: '+$('#status').textContent);$('#preview').click();await wait(()=>!$('#player').hidden||$('#status').classList.contains('error'));if($('#player').hidden)throw Error($('#status').textContent);await wait(()=>$('#player').readyState>=1);if(!Number.isFinite($('#player').duration)||$('#player').duration<=0)throw Error('Native media preview did not decode');$('#format').value='m4b';$('#render').click();await wait(()=>!$('#operation').hidden);await wait(()=>$('#operation').hidden);if($('#status').classList.contains('error'))throw Error($('#status').textContent);$('#downloads button').click();await wait(()=>$('#status').textContent.startsWith('Saved '));$('#clear').click();await wait(()=>$('#source').value==='');await report(true,'Real native window: direct unreviewed narration, native save adapter, project export, actual Qwen proposal, decoded audio preview, bundled M4B converter, and clear.')}catch(e){await report(false,String(e.message||e).slice(0,900))}})();`
